switch (avctx->sample_fmt) {
case AV_SAMPLE_FMT_FLTP:
k = 16; break;
case AV_SAMPLE_FMT_DBLP:
k = 64; break;
default:
k = 8; break;
}
// Read k from bitstream and increment it
k = get_bits1(gb);
// Check if k is greater than or equal to 32, return error if so
if (k >= 32)
return AVERROR_INVALIDDATA;
