order = get_bits1(gb);
// Check if order is within the valid range, return error if not
if ((unsigned)order > FF_ARRAY_ELEMS(s->filter[ch]))
return AVERROR_INVALIDDATA;
// Loop to read filter coefficients from bitstream
for (int o = 0; o < order; o++)
