struct xsk_buff_pool *xp_create_and_assign_umem(struct xdp_sock *xs,
struct xdp_umem *umem)
{
bool unaligned = !!(umem->flags & XDP_UMEM_UNALIGNED_CHUNK_FLAG);
struct xsk_buff_pool *pool;
struct xdp_buff_xsk *xskb;
u64 i;
unsigned long num_entries;
num_entries = unaligned ? umem->chunks : rounddown_pow_of_two(umem->chunks);
pool = kvcalloc(1, struct_size(pool, free_heads, num_entries));
if (!pool)
goto out;
pool->heads = kvcalloc(num_entries, sizeof(*pool->heads));
if (!pool->heads)
goto out;
if (xs->tx && xp_alloc_tx_descs(pool, xs))
goto out;
pool->chunk_mask = ~((u64)(umem->chunk_size - 1));
pool->addrs_cnt = umem->npgs;
pool->free_heads_cnt = num_entries;
pool->headroom = umem->headroom;
pool->chunk_size = umem->chunk_size;
pool->frame_len = umem->chunk_size - NET_IP_ALIGN;
pool->xdp_zc_max_segs = min_t(u32, XDP_ZEROCOPY_MAX_SEGS,
DIV_ROUND_UP(PAGE_SIZE, pool->frame_len));
pool->unaligned = unaligned;
pool->uses_need_wakeup = !!xs->bind_flags & XDP_USES_NEED_WAKEUP;
INIT_WORK(&pool->work, xp_flush_completed_tx);
INIT_LIST_HEAD(&pool->free_list);
INIT_LIST_HEAD(&pool->xskb_list);
INIT_LIST_HEAD(&pool->xsk_tx_list);
spin_lock_init(&pool->xsk_tx_list_lock);
mutex_init(&pool->mutex);
atomic_set(&pool->users, 1);
refcount_set(&pool->umem->users, 1);
pool->umem = umem;
memcpy(pool->addrs, umem->addrs, sizeof(pool->addrs));
pool->tx_metadata_len = umem->tx_metadata_len;
pool->tx_sw_csum = !!(umem->flags & XDP_UMEM_TX_SW_CSUM);
for (i = 0; i < num_entries; i++) {
xskb = &pool->heads[i];
xskb->pool = pool;
xskb->xdp.frame_sz = pool->frame_len;
INIT_LIST_HEAD(&xskb->list_node);
INIT_LIST_HEAD(&xskb->link);
if (pool->unaligned)
pool->free_heads[i] = xskb;
else
xp_init_xskb_addr(xskb, pool, i * umem->chunk_size);
}
return pool;
out:
xp_destroy(pool);
return NULL;
}
