        if(block_type != 6)
            return AVERROR_INVALIDDATA;

        k = 1 + (avctx->sample_fmt == AV_SAMPLE_FMT_S16P);
        k = get_urice(gb, k) + 1;
        if (k >= 32)
            return AVERROR_INVALIDDATA;

        order = get_urice(gb, 2);
        if ((unsigned)order > FF_ARRAY_ELEMS(s->filter[ch]))
            return AVERROR_INVALIDDATA;
        for (int o = 0; o < order; o++)
