            samples[n + 70] += ac_out[n] + (sum >> 4);
        }

        for (int n = 0; n < 70; n++)
            samples[n] = ac_pred[n];

        for (int n = 0; n < s->nb_samples; n++)
            samples[n + 70] += ac_out[n] + samples[n + 69] * 3U - samples[n + 68] * 3U + samples[n + 67];

