folio_unlock(dst_folio);
folio_put(dst_folio);
}
continue;
}
src_folio = page_folio(src_page);
if (!(dst_pfns[i] & MIGRATE_PFN_MIGRATED) || !dst_folio) {
if (dst_folio) {
folio_unlock(dst_folio);
folio_put(dst_folio);
}
dst_folio = src_folio;
}
