m3_FreeModule(module);
}
if (wasm) {
free(wasm);
}
if (f && !feof(f)) {
fclose(f);
}
return result;
}
const char* modname_from_fn(const char* fn) {
const char* sep = "/\\:*?";
char c;
while ((c = *sep++)) {
const char* off = strrchr(fn, c) + 1;
fn = (fn < off) ? off : fn;
}
return fn;
}
