unsigned char *wasm = NULL;
size_t fsize = 0;
FILE* f = fopen(fn, "rb");
if (!f) {
return m3Err_fileOpenFailed;
}
fseek(f, 0, SEEK_END);
fsize = ftell(f);
rewind(f);
