temp_size = get_unaligned_le32(&dir_index->size) + 1;
index_list_size += temp_size;
dir_index = (void *)dir_index + sizeof(*dir_index) + temp_size;
count++;
}
return sizeof(*temp_buffer) + index_list_size +
temp_count * SQFS_DIR_INDEX_BASE_LENGTH;
