// Assume that u32 and u64 are defined as follows:
typedef uint32_t u32;
typedef uint64_t u64;
typedef uint16_t u16;
// Dummy implementation for unaligned little-endian reads.
// In real code these would convert from little-endian to host order if needed.
static inline u16 get_unaligned_le16(const void *p)
{
return *(const u16 *)p;
